import { useEffect, useRef, useState, type FormEvent } from 'react';
import {
  createSqlSource,
  type SqlColumn,
  type SqlProvider,
  type SqlSource,
  type SqlView,
} from '@granum-grid/sql';
import { loadDatabase, readerFor } from './data/duckdb';
import { describeView, sqlDataset, sqlDetails, type SqlDetails } from './datasets/sql';
import { formatCount, type DemoDataset } from './datasets/types';

/** Revisions the panel offers to reopen; the source keeps the same number of tables. */
const KEPT = 3;

/**
 * A million deterministic requests, generated by DuckDB in this tab: about 35 days at one
 * request every 3 seconds, with slow stretches and a few failures to find.
 */
const SAMPLE = `CREATE OR REPLACE TABLE granum_sample AS SELECT
  TIMESTAMP '2026-09-01' + to_seconds(i * 3) AS time,
  ['auth', 'api', 'search', 'checkout', 'db'][i % 5 + 1] AS service,
  ['GET', 'GET', 'POST', 'PUT'][CAST(hash(i) % 4 AS INTEGER) + 1] AS method,
  '/v1/' || ['orders', 'users', 'search', 'cart', 'pay'][CAST(hash(i * 3) % 5 AS INTEGER) + 1] || '/' || hash(i * 5) % 10000 AS path,
  CASE WHEN hash(i * 7) % 1000 < 3 THEN 503 WHEN hash(i * 7) % 1000 < 25 THEN 404 ELSE 200 END AS status,
  round(18 + (hash(i * 11) % 600) / 10.0
    + CASE WHEN (i // 25000) % 13 = 7 THEN (hash(i * 13) % 9000) / 10.0 ELSE 0 END, 1) AS latency_ms
FROM range(1000000) t(i)`;

/**
 * A first view: the first time column for dates and chapters, and a number for the map,
 * preferring a measurement (decimal or floating point) over a code or an identifier.
 */
function firstView(columns: readonly SqlColumn[]): SqlView {
  const time = columns.find((column) => column.kind === 'time')?.name;
  const numbers = columns.filter((column) => column.kind === 'number');
  const measured = (column: SqlColumn) => /^(DOUBLE|FLOAT|REAL|DECIMAL)/i.test(column.type);
  const identifier = (column: SqlColumn) => /(^|_)(id|index|row)$/i.test(column.name);
  const metric = (
    numbers.find(measured) ??
    numbers.find((column) => !identifier(column)) ??
    numbers[0]
  )?.name;
  return {
    metric,
    timeColumn: time,
    chapters: time ? 'day' : undefined,
    peaks: metric ? 8 : 0,
  };
}

let uploads = 0;

export function SqlImport({
  dataset,
  onLoad,
}: {
  dataset: DemoDataset;
  onLoad(dataset: DemoDataset): void;
}) {
  const info = sqlDetails(dataset.provider);
  // Only a revision of an opened file has details, and every such provider is a SqlProvider.
  const view = info ? (dataset.provider as unknown as SqlProvider).view : null;
  const [status, setStatus] = useState('');
  const [error, setError] = useState('');
  const [where, setWhere] = useState(view?.whereSql ?? '');
  const [sort, setSort] = useState(view?.orderBy?.[0]?.column ?? '');
  const [descending, setDescending] = useState(!!view?.orderBy?.[0]?.descending);
  const [metric, setMetric] = useState(view?.metric ?? '');
  const [columns, setColumns] = useState<SqlColumn[]>([]);
  const [dragging, setDragging] = useState(false);
  const pending = useRef<AbortController | null>(null);
  useEffect(() => () => pending.current?.abort(), []);
  useEffect(() => {
    if (!info) return;
    const controller = new AbortController();
    info.source.columns(controller.signal).then(setColumns, () => {});
    return () => controller.abort();
  }, [info]);

  /** Run one step at a time; a new action cancels the one in progress. */
  async function run(task: (signal: AbortSignal) => Promise<DemoDataset>) {
    pending.current?.abort();
    const controller = (pending.current = new AbortController());
    setError('');
    try {
      const next = await task(controller.signal);
      if (!controller.signal.aborted) onLoad(next);
    } catch (reason) {
      if (!controller.signal.aborted)
        setError(reason instanceof Error ? reason.message : 'DuckDB could not open this.');
    } finally {
      if (pending.current === controller) setStatus('');
    }
  }

  async function first(
    source: SqlSource,
    details: Omit<SqlDetails, 'source' | 'views'>,
    signal: AbortSignal,
  ) {
    setStatus('Reading columns…');
    const view = firstView(await source.columns(signal));
    setStatus('Copying rows into the first revision…');
    const provider = await source.open(view, signal);
    return sqlDataset(provider, { ...details, source, views: [view] });
  }

  const openFile = (file: File) =>
    run(async (signal) => {
      const name = `upload-${++uploads}-${file.name}`;
      const from = readerFor(file.name);
      if (!from) throw new Error('Choose a .parquet, .csv, .tsv, .json, .jsonl, or .ndjson file.');
      setStatus('Loading DuckDB, about 8 MB the first time…');
      const db = await loadDatabase();
      await db.addFile(name, file);
      const source = createSqlSource({
        query: db.query,
        id: `${file.name}:${file.size}:${file.lastModified}`,
        from: readerFor(name)!,
        keepRevisions: KEPT,
      });
      return first(
        source,
        { name: file.name, bytes: file.size, sample: false, engine: db.version },
        signal,
      );
    });

  const openSample = () =>
    run(async (signal) => {
      setStatus('Loading DuckDB, about 8 MB the first time…');
      const db = await loadDatabase();
      setStatus('Generating a million requests…');
      await db.query(SAMPLE, [], signal);
      const source = createSqlSource({
        query: db.query,
        id: 'granum-sample',
        from: 'granum_sample',
        keepRevisions: KEPT,
      });
      return first(
        source,
        { name: 'A million generated requests', bytes: null, sample: true, engine: db.version },
        signal,
      );
    });

  const reopen = (next: SqlView) =>
    run(async (signal) => {
      if (!info) throw new Error('Open a file first.');
      setStatus('Building the revision…');
      const provider = await info.source.open(next, signal);
      const key = describeView(next);
      const views = [next, ...info.views.filter((item) => describeView(item) !== key)].slice(
        0,
        KEPT,
      );
      return sqlDataset(provider, { ...info, views });
    });

  const apply = (event: FormEvent) => {
    event.preventDefault();
    if (!view) return;
    void reopen({
      ...view,
      whereSql: where.trim() || undefined,
      orderBy: sort ? [{ column: sort, descending }] : undefined,
      metric: metric || undefined,
      peaks: metric ? 8 : 0,
    });
  };

  return (
    <div
      className="trace-import sql-import"
      data-dragging={dragging || undefined}
      data-empty={!info || undefined}
      onDragOver={(event) => {
        event.preventDefault();
        setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={(event) => {
        event.preventDefault();
        setDragging(false);
        const file = event.dataTransfer.files[0];
        if (file) void openFile(file);
      }}
    >
      <div className="sql-open">
        <label className="trace-file-button">
          {info && !info.sample ? 'Open another file' : 'Open a file'}
          <input
            type="file"
            accept=".parquet,.csv,.tsv,.txt,.json,.jsonl,.ndjson"
            aria-label="Open a Parquet, CSV, or JSON file"
            onChange={(event) => {
              const file = event.currentTarget.files?.[0];
              event.currentTarget.value = '';
              if (file) void openFile(file);
            }}
          />
        </label>
        <button type="button" onClick={() => void openSample()} disabled={!!status}>
          Make a sample of a million requests
        </button>
        <span>or drop a file here · Parquet, CSV, JSON · nothing is uploaded</span>
      </div>
      {info && view && (
        <form className="sql-view" onSubmit={apply} aria-label="Revision">
          <label>
            Where
            <input
              value={where}
              onChange={(event) => setWhere(event.currentTarget.value)}
              placeholder="status >= 500 AND service = 'api'"
              aria-describedby="sql-where-help"
              spellCheck={false}
            />
          </label>
          <label>
            Order by
            <select value={sort} onChange={(event) => setSort(event.currentTarget.value)}>
              <option value="">File order</option>
              {columns.map((column) => (
                <option key={column.name} value={column.name}>
                  {column.name}
                </option>
              ))}
            </select>
          </label>
          <label className="sql-check">
            <input
              type="checkbox"
              checked={descending}
              disabled={!sort}
              onChange={(event) => setDescending(event.currentTarget.checked)}
            />
            Descending
          </label>
          <label>
            Map
            <select value={metric} onChange={(event) => setMetric(event.currentTarget.value)}>
              <option value="">None</option>
              {columns
                .filter((column) => column.kind === 'number')
                .map((column) => (
                  <option key={column.name} value={column.name}>
                    {column.name}
                  </option>
                ))}
            </select>
          </label>
          <button type="submit" disabled={!!status}>
            New revision
          </button>
          <small id="sql-where-help">
            A DuckDB condition, run in this tab only. Each revision copies the matching rows in
            order, so its addresses are its own.
          </small>
        </form>
      )}
      {info && info.views.length > 1 && (
        <nav className="sql-revisions" aria-label="Kept revisions">
          {info.views.map((item) => {
            const key = describeView(item);
            const current = key === describeView(view!);
            return (
              <button
                key={key}
                type="button"
                aria-current={current || undefined}
                disabled={current || !!status}
                onClick={() => void reopen(item)}
              >
                {key}
              </button>
            );
          })}
        </nav>
      )}
      {status && <span role="status">{status}</span>}
      {info && !status && (
        <span>
          {formatCount(dataset.provider.rowCount)} rows in this revision · DuckDB {info.engine}
        </span>
      )}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
